import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'
import Lightbox from 'yet-another-react-lightbox'
import Zoom from 'yet-another-react-lightbox/plugins/zoom'
import Fullscreen from 'yet-another-react-lightbox/plugins/fullscreen'
import 'yet-another-react-lightbox/styles.css'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"

interface ImageSharpEdge {
  node: {
    publicURL: string
    childImageSharp: {
      thumb: IGatsbyImageData
      full: IGatsbyImageData
    }
  }
}

interface PageProps {
  data: {
    images: {
      edges: ImageSharpEdge[]
    }
  }
  pageContext: {
    galleryName: string
    galleryTitle: string
  }
}

const GalleryTemplate: React.FC<PageProps> = ({ data, pageContext }) => {
  const [lightboxIndex, setLightboxIndex] = React.useState(-1)

  // Transform images for lightbox
  const lightboxSlides = data.images.edges.map(({ node }) => {
    return {
      src: node.publicURL,
    }
  })

  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <Link to="/photography" className="back-link">
          ← Back to Photography
        </Link>
        <h1>{pageContext.galleryTitle}</h1>
        <p>{data.images.edges.length} {data.images.edges.length === 1 ? 'image' : 'images'} in this collection</p>
        <div className="accent-line"></div>
      </div>
      <div className="masonry-gallery">
        {data.images.edges.map(({ node }, index) => {
          const image = getImage(node.childImageSharp.thumb)
          if (!image) return null

          return (
            <div
              key={index}
              className="gallery-item"
              onClick={() => setLightboxIndex(index)}
            >
              <GatsbyImage
                image={image}
                alt={`${pageContext.galleryTitle} - Image ${index + 1}`}
                className="gallery-thumb"
              />
            </div>
          )
        })}
      </div>
      <div className="back-to-top-container">
        <button
          className="back-to-top"
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
        >
          ⬆ Back to Top
        </button>
      </div>
      <Lightbox
        open={lightboxIndex >= 0}
        close={() => setLightboxIndex(-1)}
        index={lightboxIndex}
        slides={lightboxSlides}
        plugins={[Zoom, Fullscreen]}
        zoom={{
          maxZoomPixelRatio: 3,
          scrollToZoom: true,
        }}
        carousel={{
          finite: false,
          spacing: 0,
          padding: 0
        }}
        animation={{
          fade: 250,
          swipe: 500,
          navigation: 500,
          easing: {
            fade: "ease-out",
            swipe: "ease-in-out",
            navigation: "ease-in-out"
          }
        }}
      />
      <Footer />
    </div>
  )
}

export const query = graphql`
  query GalleryTemplateQuery($galleryName: String!) {
    images: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        relativeDirectory: { eq: $galleryName }
      }
      sort: { name: ASC }
    ) {
      edges {
        node {
          publicURL
          childImageSharp {
            thumb: gatsbyImageData(
              width: 800
              placeholder: BLURRED
            )
            full: gatsbyImageData(layout: FULL_WIDTH)
          }
        }
      }
    }
  }
`

export default GalleryTemplate
